        env: { ...env, ...overrides }, encoding: 'utf8', timeout: 10000, windowsHide: true,
    });
    assert.equal(run('dist/admin.js').status, 1);
    assert.equal(run('dist/admin.js', ['?', 'extra']).status, 1);
